python3 - <<'PY'
import json
d=json.load(open("transcript/tic-tac-toe-no-draw-rule-design.json"))
print(json.dumps(d["info"],indent=1)[:2000])
for i,m in enumerate(d["messages"]):
    role=m.get("role")
    parts=m.get("parts") or m.get("content")
    txt=""
    if isinstance(parts,list):
        for p in parts:
            if isinstance(p,dict):
                txt+=str(p.get("text") or p.get("content") or "")
            else:
                txt+=str(p)
    else:
        txt=str(parts)
    print(f"\n===== [{i}] {role} ({len(txt)} chars) =====")
    print(txt[:1500])
